def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or s.get('last_error_kind') in ('unknown_col', 'syntax'):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_handling'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'mutation_verify'
    elif p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        stage = 'ready_to_commit_candidate'
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Schema or identifier issue: use SHOW TABLES, DESCRIBE the target table, or inspect a few sample rows. In MySQL, wrap table and column names containing spaces, punctuation, parentheses, or reserved words in backticks.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT: inspect distinct or sample values for the filtered columns, then match stored text exactly. Numeric-looking fields may contain commas, percent signs, spaces, or be stored as text, so use the displayed literal format rather than a normalized number.'
    elif stage == 'text_numeric_handling':
        msg = 'Text numeric handling: for ranking, min/max, sum, or ordering over numeric text, clean separators such as commas or percent signs with REPLACE and CAST to SIGNED or DECIMAL. Preserve original text only when the final answer asks for the stored value.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated SQL loop: change the debugging step instead of rerunning the same query. Probe schema, sample values, distinct filter values, or a simpler aggregate, then adjust quoting, literals, casts, or grouping.'
    elif stage == 'mutation_verify':
        msg = 'Mutation task: after INSERT, UPDATE, or DELETE, an empty tool result can still mean success. Verify the affected rows or final table state with SELECT, then commit without treating [] as failure.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Before committing, match the answer shape to the question and SQL result. For totals or aggregates, submit the numeric result rather than dropping trailing zeros or percent signs unless normalization is requested; for best/worst/rank questions, use the numeric rank or position, not a label.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    answers = a.get('answers')
    if p.get('commit_before_sql') or (s.get('sql_count') or 0) == 0:
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect the table before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and s.get('mutation_attempted')):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task. Use the SQL result values, preserving exact formatting when appropriate.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted'):
        return {'kind': 'block_and_prompt', 'message': 'This is a data-changing task. Execute the INSERT, UPDATE, or DELETE first; final text alone will not change the database state.'}
    return None
